declare(strict_types=1);require dirname(__DIR__).'/app/bootstrap.php';$raw=json_decode(file_get_contents('php://input'),true)?:[];$url=trim((string)($raw['url']??''));if(!filter_var($url,FILTER_VALIDATE_URL))json_response(['ok'=>false,'error'=>['code'=>'INVALID_URL']],422);$canonical=canonicalize_url($url);$hash=hash('sha256',$canonical);$s=$pdo->prepare('SELECT id,public_id,title,canonical_url,status FROM sources WHERE canonical_url_hash=?');$s->execute([$hash]);$source=$s->fetch();$count=0;if($source){$q=$pdo->prepare("SELECT COUNT(*) FROM annotations WHERE source_id=? AND visibility='public' AND status='published'");$q->execute([$source['id']]);$count=(int)$q->fetchColumn();}$u=current_user($pdo);json_response(['ok'=>true,'data'=>['source'=>$source,'canonical_url'=>$canonical,'annotation_count'=>$count,'authenticated'=>(bool)$u,'presence_mode'=>$u['live_presence_mode']??'off']]);
